descriptor.templateCss:
.device-table-wrapper {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: #fff;
  font-family: 'Open Sans', sans-serif;
  overflow: hidden;
}

.device-search-bar {
  display: flex;
  align-items: center;
  padding: 10px 10px 0;
  flex-shrink: 0;
}

.search-input-wrap {
  position: relative;
  width: 100%;
  max-width: 320px;
}

.search-input-wrap input {
  width: 100%;
  padding: 9px 32px 9px 12px;
  border: 1px solid #ccc;
  border-radius: 8px;
  font-size: 14px;
  font-family: 'Open Sans', sans-serif;
  background: #fff;
  color: #333;
  outline: none;
  transition: border-color 0.2s;
  box-sizing: border-box;
}

.search-input-wrap input:focus {
  border-color: #999;
  box-shadow: 0 0 0 2px rgba(0,0,0,0.06);
}

.search-input-wrap input::placeholder {
  color: #aaa;
}

.search-clear {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 20px;
  color: #999;
  cursor: pointer;
  display: none;
  line-height: 1;
  padding: 2px 4px;
}

.search-clear:hover {
  color: #555;
}

.device-table-scroll {
  flex: 1;
  overflow: auto;
  padding: 0 10px 10px;
  box-sizing: border-box;
}

.device-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  color: #333;
}

.device-table thead th {
  position: sticky;
  top: 0;
  background: #fafafa;
  border-bottom: 2px solid rgba(0, 66, 37, 0.18);
  text-align: left;
  padding: 10px 12px;
  font-weight: 600;
  color: #444;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  z-index: 1;
}

.device-table thead th.not-sortable {
  cursor: default;
}

.device-table thead th .sort-arrow {
  display: inline-block;
  margin-left: 4px;
  font-size: 11px;
  color: #bbb;
}

.device-table thead th.sorted .sort-arrow {
  color: #2e7d32;
}

.device-table tbody tr {
  cursor: pointer;
  border-bottom: 1px solid #eee;
  transition: background 0.1s;
}

.device-table tbody tr:hover {
  background: #f5f7f5;
}

.device-table td {
  padding: 9px 12px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.name-cell-inner {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.status-dot.online {
  background: #2e7d32;
  box-shadow: 0 0 5px rgba(46, 125, 50, 0.5);
}

.status-dot.offline {
  background: #bbb;
}

.table-loading, .table-empty {
  text-align: center;
  color: #999;
  padding: 40px;
  font-size: 14px;
}

descriptor.controllerScript:
var self = this;
var searchDebounceTimer = null;

self.onInit = function() {
    var settings = self.ctx.settings || {};
    self.ctx._settings = {
        enableSearch: settings.enableSearch !== false,
        searchThreshold: (typeof settings.searchThreshold === 'number') ? settings.searchThreshold : 5,
        persistState: settings.persistState !== false,
        storageType: settings.storageType || 'session',
        statusKey: (typeof settings.statusKey === 'string') ? settings.statusKey : 'active',
        defaultSortKey: settings.defaultSortKey || '__name',
        defaultSortOrder: settings.defaultSortOrder || 'asc',
        showNameColumn: settings.showNameColumn !== false,
        sortNameColumnByStatus: !!settings.sortNameColumnByStatus
    };

    self.ctx._storageKey = buildStorageKey();
    self.ctx._filterText = '';
    self.ctx._sortKey = self.ctx._settings.defaultSortKey;
    self.ctx._sortOrder = self.ctx._settings.defaultSortOrder;
    self.ctx._allEntities = {};

    restoreState();
    buildColumns();
    setupSearch();

    if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.data) {
        renderTable(self.ctx.defaultSubscription.data);
    }
};

self.onDataUpdated = function() {
    if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.data) {
        renderTable(self.ctx.defaultSubscription.data);
    }
};

function buildStorageKey() {
    var stateId = 'state';
    try {
        if (self.ctx.stateController && self.ctx.stateController.getStateId) {
            stateId = self.ctx.stateController.getStateId() || stateId;
        }
    } catch (e) {}
    var title = (self.ctx.widgetConfig && self.ctx.widgetConfig.title) ||
        (self.ctx.widget && self.ctx.widget.title) || 'devicetable';
    return 'tb_device_table_' + stateId + '_' + String(title).replace(/\s+/g, '_');
}

function getStorage() {
    return self.ctx._settings.storageType === 'local' ? window.localStorage : window.sessionStorage;
}

function restoreState() {
    if (!self.ctx._settings.persistState) return;
    try {
        var raw = getStorage().getItem(self.ctx._storageKey);
        if (!raw) return;
        var saved = JSON.parse(raw);
        if (saved) {
            self.ctx._filterText = saved.filterText || '';
            self.ctx._sortKey = saved.sortKey || self.ctx._sortKey;
            self.ctx._sortOrder = saved.sortOrder || self.ctx._sortOrder;
        }
    } catch (e) {}
}

function saveState() {
    if (!self.ctx._settings.persistState) return;
    try {
        getStorage().setItem(self.ctx._storageKey, JSON.stringify({
            filterText: self.ctx._filterText,
            sortKey: self.ctx._sortKey,
            sortOrder: self.ctx._sortOrder
        }));
    } catch (e) {}
}

function buildColumns() {
    var dataKeys = (self.ctx.datasources && self.ctx.datasources[0] && self.ctx.datasources[0].dataKeys) || [];
    var columns = [];

    if (self.ctx._settings.showNameColumn) {
        columns.push({
            key: '__name',
            label: 'Device',
            sortable: true,
            align: 'left',
            isName: true
        });
    }

    dataKeys.forEach(function(dk) {
        var ks = dk.settings || {};
        columns.push({
            key: dk.name,
            label: dk.label || dk.name,
            align: ks.align || 'left',
            sortable: ks.sortable !== false,
            width: ks.columnWidth || null,
            units: dk.units || '',
            decimals: (typeof dk.decimals === 'number') ? dk.decimals : null,
            hideColumn: !!ks.hideColumn,
            displayAsStatusDot: !!ks.displayAsStatusDot,
            useCellContentFunction: !!ks.useCellContentFunction,
            cellContentFunction: ks.cellContentFunction || '',
            useCellStyleFunction: !!ks.useCellStyleFunction,
            cellStyleFunction: ks.cellStyleFunction || ''
        });
    });

    self.ctx._columns = columns;
    renderHeader();
}

function visibleColumns() {
    return (self.ctx._columns || []).filter(function(col) { return !col.hideColumn; });
}

function renderHeader() {
    var head = self.ctx.$container.find('#device-table-head');
    head.empty();

    visibleColumns().forEach(function(col) {
        var th = $('<th></th>').text(col.label);
        th.attr('data-key', col.key);
        th.css('text-align', col.align || 'left');
        if (col.width) th.css('width', col.width);

        if (!col.sortable) {
            th.addClass('not-sortable');
        } else {
            var arrow = $('<span class="sort-arrow">↕</span>');
            if (self.ctx._sortKey === col.key) {
                th.addClass('sorted');
                arrow.text(self.ctx._sortOrder === 'asc' ? '▲' : '▼');
            }
            th.append(arrow);
            th.on('click', function() {
                if (self.ctx._sortKey === col.key) {
                    self.ctx._sortOrder = self.ctx._sortOrder === 'asc' ? 'desc' : 'asc';
                } else {
                    self.ctx._sortKey = col.key;
                    self.ctx._sortOrder = 'asc';
                }
                saveState();
                renderHeader();
                filterSortAndRender();
            });
        }
        head.append(th);
    });
}

function setupSearch() {
    var input = self.ctx.$container.find('#deviceSearchInput');
    var clearBtn = self.ctx.$container.find('#searchClear');

    input.val(self.ctx._filterText);
    clearBtn.css('display', self.ctx._filterText ? 'inline' : 'none');

    input.on('input', function() {
        var val = $(this).val();
        self.ctx._filterText = val.toLowerCase().trim();
        clearBtn.css('display', val.length > 0 ? 'inline' : 'none');
        if (searchDebounceTimer) clearTimeout(searchDebounceTimer);
        searchDebounceTimer = setTimeout(function() {
            saveState();
            filterSortAndRender();
        }, 200);
    });

    clearBtn.on('click', function() {
        input.val('');
        self.ctx._filterText = '';
        clearBtn.css('display', 'none');
        saveState();
        filterSortAndRender();
    });

    input.on('click', function(e) { e.stopPropagation(); });
}

function renderTable(data) {
    var body = self.ctx.$container.find('#device-table-body');

    if (!data || !data.length) {
        self.ctx._allEntities = {};
        body.empty().html('<tr><td class="table-empty" colspan="' + (visibleColumns().length || 1) + '">No devices found</td></tr>');
        self.ctx.$container.find('#deviceSearchBar').css('display', 'none');
        return;
    }

    self.ctx._allEntities = groupByEntity(data);
    var totalDevices = Object.keys(self.ctx._allEntities).length;
    var showSearch = self.ctx._settings.enableSearch && totalDevices > self.ctx._settings.searchThreshold;
    self.ctx.$container.find('#deviceSearchBar').css('display', showSearch ? 'flex' : 'none');
    filterSortAndRender();
}

function filterSortAndRender() {
    var body = self.ctx.$container.find('#device-table-body');
    body.empty();

    var entities = self.ctx._allEntities;
    var keys = Object.keys(entities);
    var filter = self.ctx._filterText || '';
    var columns = visibleColumns();

    if (keys.length === 0) {
        body.html('<tr><td class="table-empty" colspan="' + columns.length + '">No devices found</td></tr>');
        return;
    }

    var rows = [];
    keys.forEach(function(k) {
        var e = entities[k];
        e.displayName = resolveDisplayName(e);

        if (filter) {
            var searchStr = (e.displayName || '').toLowerCase();
            var vals = e.values || {};
            for (var vk in vals) {
                if (vals.hasOwnProperty(vk)) searchStr += ' ' + String(vals[vk] || '').toLowerCase();
            }
            if (searchStr.indexOf(filter) === -1) return;
        }
        rows.push(e);
    });

    if (!rows.length) {
        body.html('<tr><td class="table-empty" colspan="' + columns.length + '">No matching devices</td></tr>');
        return;
    }

    rows.sort(function(a, b) {
        var cmp = compareValues(getSortValue(a, self.ctx._sortKey), getSortValue(b, self.ctx._sortKey));
        return cmp * (self.ctx._sortOrder === 'desc' ? -1 : 1);
    });

    rows.forEach(function(e) {
        var tr = $('<tr></tr>');
        columns.forEach(function(col) {
            var td = $('<td></td>');
            td.css('text-align', col.align || 'left');

            if (col.isName) {
                var isOnline = self.ctx._settings.statusKey ? toBool(e.values[self.ctx._settings.statusKey]) : null;
                var inner = $('<div class="name-cell-inner"></div>');
                if (isOnline !== null) {
                    inner.append($('<span></span>').addClass('status-dot ' + (isOnline ? 'online' : 'offline')));
                }
                inner.append($('<span></span>').text(e.displayName));
                td.append(inner);
            } else {
                renderCell(td, col, e.values[col.key], e);
            }

            tr.append(td);
        });

        (function(entityData) {
            tr.on('click', function() { navigateToDevice(entityData); });
        })(e);

        body.append(tr);
    });
}

function renderCell(td, col, value, entity) {
    if (col.useCellContentFunction && col.cellContentFunction) {
        try {
            var fn = new Function('value', 'entityData', 'ctx', col.cellContentFunction);
            var html = fn(value, entity, self.ctx);
            td.html(html != null ? html : '');
        } catch (e) {
            td.text('err');
        }
    } else if (col.displayAsStatusDot) {
        var on = toBool(value);
        td.html('<span class="status-dot ' + (on ? 'online' : 'offline') + '"></span>');
    } else {
        td.text(formatValue(value, col));
    }

    if (col.useCellStyleFunction && col.cellStyleFunction) {
        try {
            var sfn = new Function('value', 'entityData', 'ctx', col.cellStyleFunction);
            var style = sfn(value, entity, self.ctx);
            if (style) td.css(style);
        } catch (e) {}
    }
}

function formatValue(value, col) {
    if (value === undefined || value === null || value === '') return '--';
    if (typeof value === 'boolean') return value ? 'Yes' : 'No';
    var str = String(value).trim();
    var num = parseFloat(str);
    if (!isNaN(num) && /^-?\d+(\.\d+)?$/.test(str)) {
        var out = (col.decimals !== null) ? num.toFixed(col.decimals) : str;
        return col.units ? (out + ' ' + col.units) : out;
    }
    return str;
}

function getSortValue(entity, key) {
    if (key === '__name') {
        var name = (entity.displayName || '').toLowerCase();
        if (self.ctx._settings.sortNameColumnByStatus && self.ctx._settings.statusKey) {
            var online = toBool(entity.values[self.ctx._settings.statusKey]);
            return (online ? '0_' : '1_') + name;
        }
        return name;
    }
    var v = entity.values[key];
    return (v === undefined || v === null) ? '' : v;
}

function compareValues(a, b) {
    var na = parseFloat(a), nb = parseFloat(b);
    if (!isNaN(na) && !isNaN(nb) && String(a).trim() !== '' && String(b).trim() !== '') {
        return na - nb;
    }
    a = String(a).toLowerCase();
    b = String(b).toLowerCase();
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

function resolveDisplayName(e) {
    return e.values.deviceName || e.values.label || e.name || 'Device';
}

function groupByEntity(data) {
    var entities = {};
    for (var i = 0; i < data.length; i++) {
        var item = data[i];
        if (!item || !item.datasource) continue;
        var entityId = item.datasource.entityId;
        if (!entityId) continue;

        if (!entities[entityId]) {
            entities[entityId] = {
                name: item.datasource.entityName || item.datasource.name || 'Unknown',
                entityId: entityId,
                entityType: item.datasource.entityType || 'DEVICE',
                values: {}
            };
        }

        var keyName = '';
        if (item.dataKey) {
            keyName = item.dataKey.name || item.dataKey.label || item.dataKey.key || '';
        }

        if (keyName && item.data && item.data.length > 0) {
            var last = item.data[item.data.length - 1];
            entities[entityId].values[keyName] = Array.isArray(last) ? last[1] : last;
        }
    }
    return entities;
}

function navigateToDevice(entityData) {
    var entityId = {
        id: entityData.entityId,
        entityType: entityData.entityType || 'DEVICE'
    };

    var descriptors = self.ctx.actionsApi.getActionDescriptors('rowClick');
    if (descriptors && descriptors.length > 0) {
        self.ctx.actionsApi.handleWidgetAction(
            {}, descriptors[0], entityId, entityData.name, null, null
        );
    }
}

function toBool(val) {
    return val === true || val === 'true' || val === 1 || val === '1' || val === 'ON';
}

self.onDestroy = function() {
    if (searchDebounceTimer) clearTimeout(searchDebounceTimer);
    self.ctx.$container.find('.device-table tbody tr').off('click');
    self.ctx.$container.find('#deviceSearchInput').off('input click');
    self.ctx.$container.find('#searchClear').off('click');
    self.ctx.$container.find('thead th').off('click');
};

